# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: digest
def digest(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: emit
def emit(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return emit(digest(fold(sift(shape(raw)))))

